const BRAND_CSS="\n@font-face{font-family:Anton;src:url('/assets/fonts/anton-props.woff2') format('woff2');font-display:swap}\n@font-face{font-family:Space;src:url('/assets/fonts/space-grotesk-props.woff2') format('woff2');font-weight:300 700;font-display:swap}\n@font-face{font-family:\"Space Grotesk\";src:url('/assets/fonts/space-grotesk-props.woff2') format('woff2');font-weight:300 700;font-display:swap}\n@font-face{font-family:\"Instrument Serif\";font-style:italic;src:url(data:font/woff2;base64,) format('woff2');font-display:swap}\n:root{\n  color-scheme:light;\n  --paper:#faf4e7;--chalk:#fffdf5;--ink:#141414;--smoke:#5a554e;--rule:#e4dcc8;\n  --blue:#1036af;--yellow:#ffd63b;--red:#e8382b;--red-text:#c42a1e;--mint:#aeef9d;\n  --display:Anton,Impact,\"Arial Narrow\",sans-serif;\n  --body:Space,\"Helvetica Neue\",Arial,sans-serif;\n  --serif:\"Instrument Serif\",Georgia,\"Times New Roman\",serif;\n  --gutter:clamp(20px,5.5vw,100px);\n  --max:calc(1560px + 2 * var(--gutter));\n  --line:2px solid var(--ink);\n  --shadow:5px 5px 0 var(--ink);\n}\n*,*::before,*::after{box-sizing:border-box}\nhtml{scroll-behavior:auto;-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--paper);color:var(--ink);font:400 1rem/1.55 var(--body)}\nimg,svg{display:block}\na{color:inherit}\n:focus-visible{outline:3px solid var(--red);outline-offset:3px}\na,button{-webkit-tap-highlight-color:transparent}\n.visually-hidden{position:absolute!important;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n.skip{position:absolute;left:12px;top:-60px;z-index:50;background:var(--yellow);border:var(--line);padding:10px 14px;font-weight:700;text-decoration:none}\n.skip:focus{top:12px}\n.wrap{width:100%;max-width:var(--max);margin:0 auto;padding-left:var(--gutter);padding-right:var(--gutter)}\n.label{font:700 .74rem/1.3 var(--body);letter-spacing:.14em;text-transform:uppercase}\n.icon{width:1em;height:1em;flex:none;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}\n\n/* Buttons */\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:50px;padding:12px 20px;border:var(--line);background:var(--yellow);color:var(--ink);box-shadow:var(--shadow);font:700 .8rem/1 var(--body);letter-spacing:.08em;text-transform:uppercase;text-decoration:none;cursor:pointer;transition:transform .12s ease,box-shadow .12s ease}\n.btn:hover{transform:translate(-2px,-2px);box-shadow:7px 7px 0 var(--ink)}\n.btn:active{transform:translate(3px,3px);box-shadow:2px 2px 0 var(--ink)}\n.btn--ghost{background:var(--paper);box-shadow:none}\n.btn--ghost:hover{box-shadow:var(--shadow)}\n.btn--ink{background:var(--ink);color:var(--paper);box-shadow:5px 5px 0 var(--red)}\n.btn--ink:hover{box-shadow:7px 7px 0 var(--red)}\n.btn--sm{min-height:42px;padding:9px 14px;font-size:.72rem}\n\n/* Hero */\n.hero{border-bottom:3px solid var(--ink)}\n.hero .wrap{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(320px,.9fr);gap:clamp(32px,5vw,80px);align-items:center;padding-top:clamp(48px,7vw,104px);padding-bottom:clamp(56px,7.5vw,112px)}\n.kicker{display:inline-flex;align-items:center;gap:10px}\n.kicker::before{content:\"\";width:11px;height:11px;border-radius:50%;background:var(--red)}\n.hero h1{font:400 clamp(4.6rem,10.4vw,10.6rem)/.88 var(--display);letter-spacing:-.03em;margin:22px 0 6px;text-transform:uppercase}\n.hero h1 .blue{color:var(--blue)}\n.hero .into{font:italic 400 clamp(2.6rem,5.6vw,5.4rem)/1 var(--serif);color:var(--red);margin:0 0 26px;letter-spacing:-.01em}\n.hero .lede{max-width:520px;margin:0;font-size:clamp(1.02rem,1.45vw,1.22rem);color:var(--smoke)}\n.hero-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:32px}\n\n/* Next-up card and sign-up */\n.next-card{position:relative;background:var(--ink);color:var(--paper);border:var(--line);box-shadow:10px 10px 0 var(--red);padding:clamp(26px,3vw,40px);scroll-margin-top:24px}\n.next-card .label{color:var(--yellow)}\n.next-card h2{font:400 clamp(2.9rem,4.6vw,4.4rem)/.92 var(--display);text-transform:uppercase;margin:14px 0 14px;letter-spacing:-.01em}\n.next-card .sub{font:italic 400 clamp(1.45rem,2vw,1.8rem)/1.15 var(--serif);margin:0 0 24px;max-width:360px}\n.sticker{position:absolute;top:-30px;right:-18px;width:86px;height:86px;transform:rotate(-12deg)}\n.signup label{display:block;margin-bottom:8px;color:var(--paper)}\n.field{display:flex;border:var(--line);border-color:var(--paper);background:var(--chalk)}\n.field input{flex:1;min-width:0;border:0;background:transparent;padding:14px 14px;font:500 1rem/1.2 var(--body);color:var(--ink)}\n.field input::placeholder{color:#716b62}\n.field input:focus{outline:none}\n.field:focus-within{outline:3px solid var(--yellow);outline-offset:3px}\n.field input[aria-invalid=\"true\"]{background:#fff0ee}\n.field button{border:0;border-left:var(--line);background:var(--yellow);color:var(--ink);padding:0 18px;min-height:52px;font:700 .78rem/1 var(--body);letter-spacing:.1em;text-transform:uppercase;cursor:pointer;display:inline-flex;align-items:center;gap:10px}\n.field button:hover{background:#ffe27a}\n.field button[disabled]{cursor:progress;opacity:.75}\n.form-msg{min-height:1.5em;margin:12px 0 0;font-size:.95rem}\n.form-msg.is-error{color:#ffb3aa}\n.form-msg.is-ok{color:var(--mint)}\n.signup.is-done .field{display:none}\n.hp{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}\n.privacy{margin:6px 0 0;font-size:.82rem;color:#bdb6aa}\n\n/* Ticker */\n.ticker{background:var(--ink);color:var(--paper);border-bottom:3px solid var(--ink);overflow:hidden}\n.ticker-track{display:flex;width:max-content;animation:tick 38s linear infinite}\n.ticker ul{display:flex;align-items:center;gap:28px;margin:0;padding:15px 14px;list-style:none}\n.ticker li{display:flex;align-items:center;gap:28px;font:400 clamp(1.4rem,2.2vw,1.9rem)/1 var(--display);text-transform:uppercase;letter-spacing:.02em;white-space:nowrap}\n.ticker li::after{content:\"\";width:10px;height:10px;border-radius:50%;background:var(--red)}\n@keyframes tick{to{transform:translateX(-50%)}}\n\n/* Sections */\n.section{padding-top:clamp(64px,8.5vw,128px);padding-bottom:clamp(64px,8.5vw,128px)}\n.section h2.big{font:400 clamp(3.4rem,7.4vw,7.6rem)/.92 var(--display);text-transform:uppercase;letter-spacing:-.015em;margin:16px 0 0}\n.about .wrap{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(28px,5vw,80px);align-items:start}\n.about p{font-size:clamp(1.08rem,1.7vw,1.42rem);line-height:1.5;margin:0 0 20px;max-width:620px}\n.about .tag{display:inline-block;background:var(--red);color:var(--chalk);border:var(--line);padding:8px 14px;transform:rotate(-3deg);margin-top:8px}\n\n.events{border-top:3px solid var(--ink)}\n.events-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:28px;margin-top:40px}\n.event{display:grid;grid-template-columns:minmax(0,.62fr) minmax(0,1fr);background:var(--chalk);border:var(--line);box-shadow:9px 9px 0 var(--ink)}\n.event-copy{padding:clamp(24px,3vw,40px);display:flex;flex-direction:column;align-items:flex-start;gap:14px}\n.event-copy .label{color:var(--blue)}\n.event-copy h3{font:italic 400 clamp(2.1rem,3vw,2.9rem)/1.02 var(--serif);margin:0}\n.event-copy p{margin:0;color:var(--smoke);max-width:440px}\n.facts{display:flex;flex-wrap:wrap;gap:8px 22px;margin:4px 0 8px}\n\n.room{background:var(--blue);color:var(--paper);border-top:3px solid var(--ink)}\n.room .wrap{display:flex;align-items:flex-end;justify-content:space-between;gap:32px}\n.room h2.big .y{color:var(--yellow)}\n.room p{max-width:600px;margin:22px 0 0;font-size:1.08rem}\n\n/* Tablet */\n@media (max-width:1000px){\n  .hero .wrap{grid-template-columns:minmax(0,1fr)}\n  .next-card{max-width:560px}\n  .about .wrap{grid-template-columns:minmax(0,1fr)}\n  .events-grid{grid-template-columns:1fr}\n  .room .wrap{flex-direction:column;align-items:flex-start}\n}\n/* Phone */\n@media (max-width:720px){\n  .hero .wrap>*,.about .wrap>*{min-width:0}\n  .hero .wrap{padding-top:40px;padding-bottom:52px;gap:44px}\n  .hero h1{font-size:clamp(4.4rem,21vw,6.6rem);margin-top:18px}\n  .hero .into{font-size:clamp(2.4rem,11vw,3.2rem);margin-bottom:20px}\n  .hero-actions .btn{flex:1 1 auto}\n  .sticker{width:68px;height:68px;top:-26px;right:-8px}\n  .field{flex-direction:column;border-color:var(--paper)}\n  .field button{border-left:0;border-top:var(--line);justify-content:center;min-height:50px}\n  .event{grid-template-columns:1fr}\n}\n@media (max-width:360px){\n  /* Keep the headline inside narrow screens, even before custom fonts load. */\n  .hero h1{font-size:min(18vw,3.7rem)}\n  .next-card .sticker{right:0}\n  .section h2.big{font-size:clamp(2.8rem,14vw,3.4rem)}\n}\n@media (prefers-reduced-motion:reduce){\n  html{scroll-behavior:auto}\n  .ticker-track{animation:none}\n  .btn{transition:none}\n  .btn:hover,.btn:active{transform:none}\n}\n\n/* OffScript family pages. Shares home page design tokens and type. */\n.site-header .nav a[aria-current=\"page\"]{border-bottom-color:var(--blue)}\n.page-hero{padding-top:clamp(54px,8vw,112px);padding-bottom:clamp(54px,8vw,110px);border-bottom:3px solid var(--ink)}\n.page-hero .wrap{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(250px,.75fr);gap:clamp(26px,5vw,78px);align-items:end}\n.page-kicker{display:flex;align-items:center;gap:11px;margin-bottom:24px}\n.page-kicker:before{content:\"\";width:11px;height:11px;border-radius:50%;background:var(--red)}\n.page-title{font:400 clamp(4.6rem,9vw,9.7rem)/.98 var(--display);letter-spacing:-.02em;text-transform:uppercase;margin:0;overflow-wrap:normal}\n.page-title .blue{color:var(--blue)}\n.page-lede{max-width:465px;font-size:clamp(1.12rem,1.7vw,1.48rem);line-height:1.55;margin:0 0 10px}\n.page-lede strong{font-weight:700}\n.page-serif{font:italic 400 clamp(2.3rem,5.5vw,5rem)/1.04 var(--serif);color:var(--red);margin:13px 0 22px}\n.breadcrumb{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:22px;color:var(--smoke);font:700 .74rem/1.5 var(--body);letter-spacing:.08em;text-transform:uppercase}\n.breadcrumb a{text-decoration:none}.breadcrumb a:hover{text-decoration:underline}\n.page-section{padding-top:clamp(48px,7vw,95px);padding-bottom:clamp(50px,7vw,95px)}\n.page-section+.page-section{border-top:2px solid var(--ink)}\n.page-section h2{font:400 clamp(3rem,6.3vw,6.1rem)/1 var(--display);text-transform:uppercase;letter-spacing:-.01em;margin:11px 0 24px;max-width:820px}\n.page-section p{max-width:750px;font-size:clamp(1.04rem,1.4vw,1.22rem);line-height:1.6;margin:0 0 19px}\n.page-section.light{background:var(--chalk)}\n.page-section.ink{background:var(--ink);color:var(--paper)}\n.page-section.ink .btn{color:var(--ink)}\n.page-split{display:grid;grid-template-columns:.8fr 1.2fr;gap:clamp(30px,6vw,100px);align-items:start}\n.page-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(16px,2vw,27px);margin-top:30px}\n.paper-panel{background:var(--chalk);border:2px solid var(--ink);box-shadow:6px 6px var(--ink);padding:clamp(25px,3vw,43px)}\n.paper-panel h3{font:400 clamp(2.2rem,4.2vw,3.9rem)/1 var(--display);margin:13px 0 17px;text-transform:uppercase}\n.paper-panel p{font-size:1rem;line-height:1.6}\n.index-label{font:700 .73rem var(--body);letter-spacing:.12em;color:var(--blue)}\n.event-archive-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:clamp(18px,3vw,42px);margin-top:33px}\n.archive-card{border:2px solid var(--ink);background:var(--chalk);display:grid;grid-template-columns:.55fr 1fr;box-shadow:7px 7px var(--ink)}\n.archive-poster{background:var(--yellow);border-right:2px solid var(--ink);padding:25px;display:flex;align-items:center;justify-content:center}\n.archive-poster span{font:400 clamp(3.2rem,6vw,5.5rem)/.9 var(--display);color:var(--blue);text-align:center;transform:rotate(-5deg)}\n.archive-copy{padding:clamp(25px,3.5vw,45px)}\n.archive-copy h2{font:italic 400 clamp(2.4rem,4vw,4rem)/1 var(--serif);text-transform:none;margin:19px 0}\n.archive-copy p{font-size:1.03rem}\n.archive-when{display:flex;flex-wrap:wrap;gap:11px 24px;margin:23px 0 27px;color:var(--smoke)}\n.archive-soon{background:var(--paper);border:2px dashed var(--ink);padding:clamp(25px,3vw,40px);display:flex;flex-direction:column;align-items:flex-start;justify-content:center}\n.archive-soon h2{font:400 clamp(2.6rem,4.5vw,4.5rem)/1 var(--display);margin:16px 0}\n.archive-soon p{font-size:1.06rem}\n.cta-band{background:var(--yellow);color:var(--ink);border-top:2px solid var(--ink)}\n.cta-band .btn{background:var(--ink);color:var(--paper);box-shadow:5px 5px 0 var(--red)}\n.cta-band .wrap{display:flex;justify-content:space-between;align-items:center;gap:27px;padding-top:53px;padding-bottom:53px}\n.cta-band h2{font:400 clamp(2.6rem,5vw,5rem)/.97 var(--display);text-transform:uppercase;margin:0}\n.cta-band .btn{flex-shrink:0}\n.future-card{border:2px solid var(--ink);background:var(--paper);padding:clamp(25px,4vw,52px);box-shadow:8px 8px var(--red)}\n.future-card h3{font:400 clamp(2.8rem,5vw,5.2rem)/1 var(--display);text-transform:uppercase;margin:0 0 20px}\n.future-card p{font-size:1.12rem}\n.future-card a:not(.btn){text-decoration:underline;text-underline-offset:4px}\n.privacy-list{max-width:750px;padding:0 0 0 20px;font-size:1.05rem;line-height:1.75}\n.confirmation-page{min-height:100svh;display:grid;place-items:center;padding:30px 20px;background:var(--paper)}\n.confirmation-card{max-width:660px;width:100%;border:2px solid var(--ink);background:var(--chalk);padding:clamp(28px,7vw,65px);box-shadow:8px 8px var(--blue)}\n.confirmation-card h1{font:400 clamp(3.6rem,8vw,6rem)/1 var(--display);margin:20px 0;text-transform:uppercase}\n.confirmation-card p{font-size:1.13rem;line-height:1.6;margin:0 0 28px}\n.confirmation-kicker{display:block;color:var(--blue);margin-top:30px}\n.back-home{color:var(--blue);text-decoration:none}\n.text-link{display:inline-block;margin-top:18px;text-decoration:underline}\n.form-consent{display:flex;align-items:flex-start;gap:10px;margin-top:17px;color:var(--paper);font:400 .9rem/1.5 var(--body);cursor:pointer}\n.form-consent input{margin:3px 0 0;flex:none;width:17px;height:17px;accent-color:var(--yellow)}\n.form-consent a{color:var(--yellow)}\n.privacy a{color:var(--yellow)}\n.home-next-links{display:flex;justify-content:flex-end;gap:14px;margin-top:28px}\n.home-next-links a{font-weight:700;color:var(--blue);text-underline-offset:4px}\n.home-join{border-top:2px solid var(--ink);background:var(--chalk)}\n.home-join .wrap{display:grid;grid-template-columns:1fr auto;gap:28px;align-items:center;padding-top:55px;padding-bottom:55px}\n.home-join h2{font:400 clamp(2.8rem,5vw,5rem)/1 var(--display);text-transform:uppercase;margin:7px 0 13px}\n.home-join p{max-width:640px;font-size:1.06rem;line-height:1.6}\n@media(max-width:1000px){.page-hero .wrap{grid-template-columns:minmax(0,1fr)}.page-split{grid-template-columns:1fr}.event-archive-grid{grid-template-columns:1fr}.home-join .wrap{grid-template-columns:1fr}}\n@media(max-width:720px){.page-hero{padding-top:43px;padding-bottom:55px}.page-title{font-size:clamp(4.2rem,17vw,6.8rem)}.page-section h2{font-size:clamp(3rem,12vw,4.8rem)}.page-pair{grid-template-columns:1fr}.archive-card{grid-template-columns:1fr}.archive-poster{min-height:175px;border-right:0;border-bottom:2px solid var(--ink)}.cta-band .wrap{flex-direction:column;align-items:start}.home-join .wrap{padding-top:48px;padding-bottom:48px}.home-next-links{justify-content:flex-start}}\n@media(max-width:360px){.page-title{font-size:clamp(3.1rem,15vw,4.2rem)}.page-section h2{font-size:clamp(2.9rem,11vw,4.1rem)}}\n\n@media(min-width:1080px){.hero h1{font-size:clamp(7.4rem,9vw,9.7rem);line-height:.94}.hero .wrap{gap:clamp(35px,6.2vw,92px)}.hero .into{margin-top:14px}.hero .lede{max-width:480px;line-height:1.6}}\n@media(max-width:1000px){.hero .wrap,.about .wrap{grid-template-columns:minmax(0,1fr)}}\n\n/* Narrow-screen headings must fit before and after custom fonts load. */\n@media(max-width:420px){.page-title{font-size:clamp(3.1rem,14vw,4.9rem)}.cta-band h2{font-size:clamp(2.2rem,9.5vw,3.6rem)}}\n.page-section p{overflow-wrap:anywhere}\n.page-pair--one{grid-template-columns:minmax(0,760px)}\n\n/* Small native cross-document transitions; older browsers use standard links. */\n@view-transition{navigation:auto}\n::view-transition-old(root){animation-duration:.12s;animation-timing-function:ease-out}\n::view-transition-new(root){animation-duration:.16s;animation-timing-function:ease-in}\n@media(prefers-reduced-motion:reduce){::view-transition-old(root),::view-transition-new(root){animation-duration:.01ms}}\n\n/* OffScript experience layer: shared header and menu, motion, story, props.\n   Loaded on every OffScript page after the base tokens. */\nhtml{scroll-padding-top:96px}\nbody.menu-open{overflow:hidden}\n.icon{transition:transform .2s ease}\n.btn:hover .icon,.text-cta:hover .icon{transform:translate(2px,-2px)}\n\n/* ---------- Header ---------- */\n.site-header{position:sticky;top:0;z-index:40;background:var(--paper);border-bottom:3px solid var(--ink);transition:transform .32s cubic-bezier(.2,.8,.2,1),box-shadow .2s ease}\n.site-header.is-scrolled{box-shadow:0 6px 0 rgba(20,20,20,.06)}\n.site-header .wrap{display:flex;align-items:center;gap:clamp(16px,3vw,44px);padding-top:10px;padding-bottom:10px}\n.brand{display:inline-flex;color:var(--ink);text-decoration:none;flex:none}\n.brand svg{height:56px;width:auto;transform-origin:left center;transition:transform .25s ease}\n.site-header.is-scrolled .brand svg{transform:scale(.84)}\n.nav{display:flex;align-items:center;gap:clamp(18px,2.4vw,38px);margin-left:auto}\n.nav a{position:relative;font:700 .76rem/1 var(--body);letter-spacing:.1em;text-transform:uppercase;text-decoration:none;padding:12px 0}\n.nav a::after{content:\"\";position:absolute;left:0;right:0;bottom:4px;height:2px;background:currentColor;transform:scaleX(0);transform-origin:left;transition:transform .22s ease}\n.nav a:hover::after,.nav a[aria-current=\"page\"]::after{transform:scaleX(1)}\n.nav a[aria-current=\"page\"]{color:var(--blue)}\n.header-actions{display:flex;align-items:center;gap:10px}\n.cta-short{display:none}\n.menu-btn{display:none;align-items:center;gap:9px;min-height:44px;padding:9px 12px;background:var(--paper);border:var(--line);font:700 .72rem/1 var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--ink);cursor:pointer}\n.menu-btn .bars{display:grid;gap:4px}\n.menu-btn .bars i{display:block;width:18px;height:2px;background:var(--ink)}\n.scroll-progress{position:absolute;left:0;right:0;bottom:-3px;height:3px;background:var(--red);transform:scaleX(0);transform-origin:left;pointer-events:none}\n\n/* ---------- Menu sheet (phones and tablets) ---------- */\ndialog.menu-sheet{margin:0;padding:0;border:0;width:100%;max-width:100%;height:100%;max-height:100%;background:var(--paper);color:var(--ink);display:none;flex-direction:column;inset:0;opacity:0;transform:translateY(-12px);transition:opacity .18s ease,transform .25s cubic-bezier(.2,.8,.2,1)}\ndialog.menu-sheet[open]{display:flex}\ndialog.menu-sheet.is-open{opacity:1;transform:none}\ndialog.menu-sheet::backdrop{background:rgba(20,20,20,.55)}\n.menu-sheet-top{display:flex;align-items:center;justify-content:space-between;padding:10px var(--gutter);border-bottom:3px solid var(--ink)}\n.menu-sheet-top .brand svg{height:44px}\n.menu-close{width:46px;height:46px;display:grid;place-items:center;background:var(--yellow);border:var(--line);box-shadow:3px 3px 0 var(--ink);cursor:pointer;color:var(--ink)}\n.menu-close .icon{width:22px;height:22px}\n.menu-links{flex:1;overflow:auto;display:flex;flex-direction:column;padding:8px var(--gutter) 24px}\n.menu-links a{display:flex;align-items:baseline;gap:16px;padding:16px 0;border-bottom:2px solid var(--rule);text-decoration:none;font:400 clamp(2.5rem,10.5vw,4.2rem)/.95 var(--display);text-transform:uppercase;letter-spacing:-.01em;opacity:0;transform:translateY(10px);transition:opacity .3s ease,transform .35s cubic-bezier(.2,.8,.2,1),color .15s}\n.menu-sheet.is-open .menu-links a{opacity:1;transform:none}\n.menu-links a:nth-child(2){transition-delay:.03s}.menu-links a:nth-child(3){transition-delay:.06s}.menu-links a:nth-child(4){transition-delay:.09s}.menu-links a:nth-child(5){transition-delay:.12s}\n.menu-links small{font:700 .74rem/1 var(--body);letter-spacing:.12em;color:var(--red-text);min-width:22px}\n.menu-links a[aria-current=\"page\"]{color:var(--blue)}\n.menu-links a[aria-current=\"page\"] span::after{content:\"\";display:inline-block;width:.22em;height:.22em;margin-left:.18em;border-radius:50%;background:var(--red);vertical-align:.1em}\n.menu-links a:hover{color:var(--blue)}\n.menu-sheet-foot{display:grid;gap:16px;padding:20px var(--gutter) calc(22px + env(safe-area-inset-bottom));background:var(--ink);color:var(--paper)}\n.menu-sheet-foot .btn{width:100%}\n.menu-note{margin:0;display:flex;flex-wrap:wrap;gap:6px 12px;font-size:.92rem}\n.menu-note a{color:var(--paper);text-underline-offset:4px}\n.menu-note span{color:#8f887d}\n\n@media (max-width:900px){\n  .nav{display:none}\n  .header-actions{margin-left:auto}\n  .menu-btn{display:inline-flex}\n  .brand svg{height:46px}\n  .cta-long{display:none}.cta-short{display:inline}\n}\n@media (max-width:380px){.menu-word{display:none}.header-cta .icon{display:none}}\n\n/* ---------- Motion foundation ---------- */\nhtml.js [data-reveal]{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .8s cubic-bezier(.2,.8,.2,1)}\nhtml.js [data-reveal].is-in{opacity:1;transform:none}\n.motion-toggle{position:absolute;right:clamp(10px,2vw,24px);top:50%;translate:0 -50%;z-index:2;width:40px;height:40px;display:grid;place-items:center;background:var(--ink);color:var(--paper);border:2px solid var(--paper);cursor:pointer}\n.motion-toggle .icon{width:16px;height:16px;fill:currentColor;stroke-width:3}\n.motion-toggle--light{position:static;translate:none;background:transparent;width:44px;height:44px}\nhtml.motion-paused .ticker-track,html.motion-paused .propwall-track,html.motion-paused .hero-prop>svg{animation-play-state:paused!important}\n\n/* ---------- Hero ---------- */\n.hero{position:relative;overflow:clip}\n.hero::before{content:\"\";position:absolute;inset:0;pointer-events:none;background:repeating-linear-gradient(180deg,transparent 0 43px,rgba(20,20,20,.055) 43px 44px);-webkit-mask-image:linear-gradient(100deg,transparent 30%,#000 75%);mask-image:linear-gradient(100deg,transparent 30%,#000 75%)}\n.hero .wrap{position:relative}\n.hero-copy{min-width:0}\n.hero-title .line{display:block;overflow:hidden;padding:.04em 0 .02em;margin:-.04em 0 -.02em}\n.hero-title .word{display:inline-block}\n.hero-title .usual{position:relative;overflow:visible}\n.hero .line:last-child{overflow:visible}\n.pen-ring{position:absolute;left:-8%;top:-12%;width:116%;height:124%;overflow:visible;pointer-events:none}\n.pen-ring path,.pen-line path{fill:none;stroke:var(--red);stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke;stroke-dasharray:1 1;stroke-dashoffset:0}\n.pen-ring path{stroke-width:5}\n.into{position:relative;display:inline-block}\n.into-text{position:relative;z-index:1}\n.pen-line{position:absolute;left:0;bottom:-.1em;width:100%;height:.32em;overflow:visible}\n.pen-line path{stroke-width:3.5;stroke:var(--ink);opacity:.85}\n\nhtml.js .hero-title .word{animation:os-rise .9s cubic-bezier(.2,.8,.2,1) both}\nhtml.js .hero-title .line:first-child .word{animation-delay:.05s}\nhtml.js .hero-title .line:last-child .word:first-child{animation-delay:.16s}\nhtml.js .hero-title .usual{animation-delay:.24s}\nhtml.js .pen-ring path{stroke-dashoffset:1;animation:os-draw 1s cubic-bezier(.6,.1,.2,1) .9s forwards}\nhtml.js .pen-line path{stroke-dashoffset:1;animation:os-draw .8s cubic-bezier(.6,.1,.2,1) 1.45s forwards}\nhtml.js [data-hero-step]{animation:os-fade .8s cubic-bezier(.2,.8,.2,1) both}\nhtml.js .kicker[data-hero-step]{animation-delay:0s}\nhtml.js .into[data-hero-step]{animation-delay:.55s}\nhtml.js .lede[data-hero-step]{animation-delay:.75s}\nhtml.js .hero-actions[data-hero-step]{animation-delay:.9s}\n@keyframes os-rise{from{transform:translateY(108%);opacity:0}to{transform:none;opacity:1}}\n@keyframes os-draw{to{stroke-dashoffset:0}}\n@keyframes os-fade{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}\n\n.hero .wrap{padding-top:clamp(36px,4.6vw,76px);padding-bottom:clamp(56px,6vw,96px)}\n.hero-stage{position:relative;padding:28px 0 clamp(80px,7vw,110px);min-width:0}\n.hero-stage .next-card{z-index:2}\n.next-card:focus{outline:none}\n.hero-prop{position:absolute;z-index:1;display:block;text-decoration:none;transition:translate .5s cubic-bezier(.2,.8,.2,1)}\n.hero-prop>svg{width:100%;height:auto;animation:os-bob 7s ease-in-out infinite;transition:scale .25s ease}\n.hero-prop:hover>svg,.hero-prop:focus-visible>svg{scale:1.05}\n.hero-prop--arch{bottom:clamp(40px,6vw,90px);left:calc(-1 * clamp(150px,15vw,250px));width:clamp(190px,17vw,270px)}\n.hero-prop--arch>svg{--r:-9deg;rotate:-9deg}\n.hero-prop--bubble{right:-5%;bottom:0;width:clamp(170px,15vw,240px);z-index:3}\n.hero-prop--bubble>svg{rotate:8deg;animation-delay:-3.5s}\nhtml.js .hero-prop{animation:os-pop .8s cubic-bezier(.3,1.4,.5,1) both}\nhtml.js .hero-prop--arch{animation-delay:1.1s}\nhtml.js .hero-prop--bubble{animation-delay:1.3s}\n@keyframes os-bob{50%{transform:translateY(-9px)}}\n@keyframes os-pop{from{opacity:0;transform:scale(.6) rotate(-6deg)}to{opacity:1;transform:none}}\n\n.signup.is-closed .field{border-color:#5a554e;background:#24221f}\n.signup.is-closed .field input{color:#bdb6aa}\n.signup.is-closed .field input::placeholder{color:#8f887d}\n.signup.is-closed .field button{background:#33302c;color:#bdb6aa;border-color:#5a554e;cursor:not-allowed;opacity:1}\n.signup.is-closed .form-consent{opacity:.6;cursor:default}\n.form-msg.is-note{color:var(--yellow)}\n.form-msg.is-note::before{content:\"\";display:inline-block;width:8px;height:8px;margin-right:9px;border-radius:50%;background:var(--yellow);vertical-align:.1em}\n\n/* ---------- Ticker ---------- */\n.ticker{position:relative}\n.ticker ul{padding-right:28px}\n\n/* ---------- About ---------- */\n.about-actions{display:flex;flex-wrap:wrap;align-items:center;gap:18px 30px;margin-top:10px}\n.about .tag{margin-top:0}\n.text-cta{display:inline-flex;align-items:center;gap:9px;min-height:44px;font:700 .8rem/1 var(--body);letter-spacing:.1em;text-transform:uppercase;text-decoration:none;color:var(--ink);border-bottom:2px solid currentColor}\n.text-cta:hover{color:var(--blue)}\n\n/* ---------- Story ---------- */\n.story{border-top:3px solid var(--ink);background:var(--chalk)}\n.story-head{max-width:880px}\n.story-head h2 .blue{color:var(--blue)}\n.story-head p{margin:20px 0 0;max-width:520px;font-size:clamp(1.02rem,1.4vw,1.2rem);color:var(--smoke)}\n.story-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(32px,6vw,104px);margin-top:clamp(32px,4vw,56px)}\n.story-stage{position:sticky;top:112px;align-self:start;height:calc(100vh - 150px);max-height:620px;min-height:420px;display:flex;flex-direction:column;justify-content:center;gap:22px}\n.story-frame{position:relative;aspect-ratio:3/2;border:var(--line);background:var(--paper) radial-gradient(circle,rgba(20,20,20,.13) 1.3px,transparent 1.6px) 0 0/22px 22px;box-shadow:var(--shadow)}\n.story-prop{position:absolute;inset:7% 6%;opacity:0;transform:translateY(34px) rotate(7deg) scale(.9);transition:opacity .45s ease,transform .7s cubic-bezier(.2,.8,.2,1)}\n.story-prop.is-past{transform:translateY(-34px) rotate(-7deg) scale(.9)}\n.story-prop.is-active{opacity:1;transform:none}\n.story-prop svg{width:100%;height:100%}\n.story-meter{display:flex;align-items:center;gap:12px;font:700 .8rem/1 var(--body);letter-spacing:.1em}\n.story-meter b{font:400 2.4rem/1 var(--display);color:var(--blue);letter-spacing:0}\n.story-meter i{flex:1;height:3px;background:var(--rule);position:relative;overflow:hidden}\n.story-meter em{position:absolute;inset:0;background:var(--red);transform:scaleX(.25);transform-origin:left;transition:transform .5s cubic-bezier(.2,.8,.2,1)}\n.story-steps{list-style:none;margin:0;padding:0}\n.story-step{min-height:min(64vh,620px);display:flex;flex-direction:column;justify-content:center;padding:36px 0;border-top:2px solid var(--ink);transition:opacity .45s ease}\n.story-step:last-child{border-bottom:2px solid var(--ink)}\nhtml.js .story-step{opacity:.32}\nhtml.js .story-step.is-active{opacity:1}\n.step-no{font:700 .78rem/1 var(--body);letter-spacing:.14em;color:var(--red-text)}\n.story-step h3{font:400 clamp(2.8rem,4.9vw,5.2rem)/.94 var(--display);text-transform:uppercase;letter-spacing:-.01em;margin:14px 0 18px}\n.story-step p{margin:0;max-width:470px;font-size:clamp(1.04rem,1.45vw,1.28rem);line-height:1.55}\n.step-prop{display:none}\n\n/* ---------- Events ---------- */\n.events-top{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;flex-wrap:wrap}\n.poster{position:relative;display:grid;place-items:center;padding:30px 22px 64px;min-height:320px;overflow:hidden;border-right:var(--line);background:var(--paper) radial-gradient(circle,rgba(20,20,20,.13) 1.3px,transparent 1.6px) 0 0/20px 20px;text-decoration:none}\n.poster-prop{display:block;width:min(100%,320px);transform:rotate(-5deg);transition:transform .35s cubic-bezier(.2,.8,.2,1)}\n.poster-prop svg{width:100%;height:auto}\n.event:hover .poster-prop{transform:rotate(-1deg) scale(1.05)}\n.poster-tag{position:absolute;left:16px;bottom:16px;background:var(--ink);color:var(--paper);padding:7px 11px}\n.event{transition:transform .25s ease,box-shadow .25s ease}\n.event:hover{transform:translate(-3px,-3px);box-shadow:12px 12px 0 var(--ink)}\n\n/* ---------- Prop wall ---------- */\n.propwall{background:var(--ink);color:var(--paper);padding:clamp(56px,7vw,104px) 0 clamp(48px,6vw,88px);overflow:hidden;border-top:3px solid var(--ink)}\n.propwall-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;flex-wrap:wrap}\n.propwall .label{color:var(--yellow)}\n.propwall h2{font:400 clamp(3rem,6.6vw,6.8rem)/.92 var(--display);text-transform:uppercase;letter-spacing:-.015em;margin:14px 0 0}\n.propwall h2 .red{color:#ff5a4c}\n.propwall-actions{display:flex;align-items:center;gap:12px}\n.propwall-rail{margin-top:clamp(34px,5vw,64px);-webkit-mask-image:linear-gradient(90deg,transparent,#000 5%,#000 95%,transparent);mask-image:linear-gradient(90deg,transparent,#000 5%,#000 95%,transparent)}\n.propwall-track{display:flex;align-items:center;gap:clamp(18px,2.2vw,32px);width:max-content;margin:0;padding:18px 0;list-style:none}\n.propwall-rail{overflow:hidden;overflow:clip;touch-action:pan-y}\n.propwall-track a{display:block;width:clamp(210px,21vw,320px);rotate:var(--r,0deg);transition:rotate .3s ease,scale .3s ease}\n.propwall-track a:hover,.propwall-track a:focus-visible{rotate:0deg;scale:1.06}\n.propwall-track a:focus-visible{outline-color:var(--yellow)}\n.propwall-track svg{width:100%;height:auto}\n\n/* ---------- Family pages ---------- */\n.archive-poster{background:var(--paper) radial-gradient(circle,rgba(20,20,20,.13) 1.3px,transparent 1.6px) 0 0/20px 20px;padding:28px 18px;text-decoration:none}\n.archive-poster svg{width:min(100%,300px);height:auto;transform:rotate(-5deg);transition:transform .35s cubic-bezier(.2,.8,.2,1)}\n.archive-card:hover .archive-poster svg{transform:rotate(-1deg) scale(1.05)}\n.page-hero{position:relative;overflow:clip}\n.page-hero-prop{display:block;width:min(100%,300px);justify-self:end;rotate:6deg;margin-bottom:10px}\n.page-hero-prop svg{width:100%;height:auto}\n.prop-strip{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(14px,2vw,26px);margin-top:34px}\n.prop-strip a{display:block;transition:rotate .3s ease,scale .3s ease}\n.prop-strip a:nth-child(1){rotate:-4deg}.prop-strip a:nth-child(2){rotate:3deg}.prop-strip a:nth-child(3){rotate:-2deg}\n.prop-strip a:hover,.prop-strip a:focus-visible{rotate:0deg;scale:1.04}\n.prop-strip svg{width:100%;height:auto}\n\n/* ---------- Tablet and phone ---------- */\n@media (max-width:1000px){\n  .story-grid{grid-template-columns:minmax(0,1fr)}\n  .story-stage{display:none}\n  html.js .story-step{opacity:1}\n  .story-step{min-height:0;padding:32px 0}\n  .step-prop{display:block;width:min(100%,380px);margin-top:24px;rotate:-3deg}\n  .story-step:nth-child(even) .step-prop{rotate:3deg;margin-left:auto}\n  .step-prop svg{width:100%;height:auto}\n  .hero-stage{max-width:560px}\n  .page-hero-prop{justify-self:start;width:min(70%,260px)}\n}\n@media (max-width:1000px){\n  .hero-stage{padding-top:118px}\n  .hero-prop--arch{bottom:auto;top:0;left:-8px;width:min(52%,240px)}\n}\n@media (max-width:720px){\n  .hero-stage{padding:104px 0 84px}\n  .hero-prop--arch{width:min(56%,210px)}\n  .hero-prop--bubble{right:-6px;width:min(48%,180px)}\n  .poster{border-right:0;border-bottom:var(--line);min-height:240px;padding-bottom:60px}\n  .propwall-track a{width:200px}\n  .prop-strip{grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n  .events-top .text-cta{margin-top:-6px}\n}\n\n@media (prefers-reduced-motion:reduce){\n  html.js [data-reveal]{opacity:1;transform:none;transition:none}\n  html.js .hero-title .word,html.js [data-hero-step],html.js .hero-prop{animation:none}\n  html.js .pen-ring path,html.js .pen-line path{animation:none;stroke-dashoffset:0}\n  .hero-prop>svg{animation:none}\n  .propwall-track{animation:none}\n  .propwall-rail{-webkit-mask-image:none;mask-image:none}\n  .story-prop,.story-step,.site-header,dialog.menu-sheet,.menu-links a,.event,.poster-prop{transition:none}\n  .motion-toggle{display:none}\n}\n@media print{.site-header,.menu-sheet,.motion-toggle{display:none!important}}\n.page-hero-side{display:grid;gap:26px}\n.prop-gallery-band{margin-top:clamp(56px,7vw,96px);padding-top:clamp(36px,5vw,56px);border-top:2px solid var(--ink)}\n.props-title{font:400 clamp(2.6rem,5vw,4.8rem)/.95 var(--display);text-transform:uppercase;margin:12px 0 0}\n\n@media(min-width:1080px){.hero h1{font-size:clamp(6.4rem,7.6vw,10rem)}.hero .into{font-size:clamp(2.6rem,4.4vw,5.2rem)}}\n.propwall .btn{box-shadow:5px 5px 0 var(--red)}.propwall .btn:hover{box-shadow:7px 7px 0 var(--red)}\n\n/* ---------- Fold fit (2026-11) ----------\n   The hero is sized by screen height as well as width, so the whole message,\n   both actions and the sign-up card fit on the first screen of a laptop,\n   and the ticker peeks in below as the cue to scroll. */\n:root{--head:69px;--tick:68px}\n.brand svg{height:50px}\n.site-header .wrap{padding-top:8px;padding-bottom:8px}\n@media (min-width:1001px){\n  .hero .wrap{min-height:clamp(500px,calc(100vh - var(--head) - var(--tick)),880px);min-height:clamp(500px,calc(100svh - var(--head) - var(--tick)),880px);align-content:center;padding-top:clamp(18px,3.6svh,52px);padding-bottom:clamp(18px,3.6svh,52px);gap:clamp(32px,4.4vw,72px)}\n  .hero h1{font-size:clamp(4.2rem,min(7.2vw,13.4svh),9.6rem);margin:clamp(10px,2.2svh,22px) 0 4px}\n  .hero .into{font-size:clamp(2.1rem,min(4.1vw,7.6svh),4.8rem);margin-bottom:clamp(10px,2.4svh,24px)}\n  .hero .lede{font-size:clamp(1rem,min(1.3vw,2.7svh),1.2rem);max-width:500px;line-height:1.5}\n  .hero-actions{margin-top:clamp(14px,3svh,30px)}\n  .hero-stage{padding:clamp(16px,2.6svh,28px) 0 clamp(16px,3svh,36px)}\n  .next-card{padding:clamp(20px,3.6svh,36px) clamp(22px,2.4vw,36px)}\n  .next-card h2{font-size:clamp(2.2rem,min(3.3vw,6.6svh),4rem);margin:clamp(8px,1.4svh,14px) 0}\n  .next-card .sub{font-size:clamp(1.12rem,min(1.45vw,3.1svh),1.6rem);margin-bottom:clamp(12px,2.4svh,22px)}\n  .next-card .sticker{width:clamp(64px,10svh,86px);height:clamp(64px,10svh,86px)}\n  .signup .form-msg{min-height:1.3em;margin-top:clamp(6px,1.2svh,12px);font-size:.9rem}\n  .signup .form-consent{font-size:.86rem;line-height:1.4}\n  .signup .privacy{font-size:.78rem}\n  .hero-prop--arch{width:clamp(150px,min(15vw,30svh),260px);bottom:clamp(8px,4svh,70px)}\n  /* The bubble sits in the gap left of the card, so it never covers the form or its links. */\n  .hero-prop--bubble{width:clamp(130px,min(12vw,24svh),210px);right:auto;bottom:auto;left:calc(-1 * clamp(120px,11.5vw,200px));top:clamp(4px,3svh,36px);z-index:1}\n  .hero-prop--bubble>svg{rotate:-7deg}\n  .story-step{min-height:min(52svh,540px)}\n  .story-stage{height:calc(100svh - 150px);max-height:580px;min-height:380px}\n}\n/* Short laptops (650–760px tall): drop the second line of small print. */\n@media (min-width:1001px) and (max-height:700px){\n  .signup .privacy{display:none}\n  .next-card .sub{display:none}\n}\n/* Tablets: two columns again so the card sits beside the copy, not a screen below it. */\n@media (min-width:760px) and (max-width:1000px){\n  .hero .wrap{grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:28px;align-items:end;padding-top:48px;padding-bottom:56px}\n  .hero h1{font-size:clamp(4rem,10vw,6.4rem)}\n  .hero .into{font-size:clamp(2.2rem,5.4vw,3.4rem)}\n  .hero-stage{padding:120px 0 40px;max-width:none}\n  .next-card{max-width:none}\n  .next-card h2{font-size:clamp(2.2rem,4.6vw,3rem)}\n  .hero-prop--arch{left:-10px;width:min(56%,210px)}\n  .hero-prop--bubble{width:min(36%,140px);bottom:-30px;right:-8px}\n}\n/* Phones: tighter rhythm, one clear primary action, the card starts closer. */\n@media (max-width:720px){\n  .hero .wrap{padding-top:28px;padding-bottom:40px;gap:20px}\n  .hero h1{margin-top:14px}\n  .hero .into{margin-bottom:14px}\n  .hero .lede{font-size:1.02rem;line-height:1.5}\n  .hero-actions{display:grid;grid-template-columns:1fr;gap:4px;margin-top:22px}\n  .hero-actions .btn{width:100%}\n  .hero-actions .btn--ghost{background:transparent;border-color:transparent;box-shadow:none;min-height:46px;text-decoration:underline;text-underline-offset:5px;text-decoration-thickness:2px}\n  .hero-actions .btn--ghost:hover{box-shadow:none;transform:none}\n  .hero-stage{padding:92px 0 72px}\n  .next-card{padding:24px 20px 22px;box-shadow:7px 7px 0 var(--red)}\n  .next-card h2{font-size:clamp(2.3rem,11vw,2.9rem);margin:10px 0}\n  .next-card .sub{font-size:1.2rem;margin-bottom:16px}\n  .signup .form-consent{font-size:.86rem;line-height:1.4}\n  .section{padding-top:56px;padding-bottom:60px}\n  .section h2.big{font-size:clamp(3rem,15vw,4.2rem)}\n  .about p{font-size:1.06rem}\n  .story-step{padding:28px 0}\n  .story-step h3{font-size:clamp(2.4rem,11.5vw,3.2rem);margin:10px 0 12px}\n  .step-prop{width:min(78%,260px);margin-top:18px}\n  .events-grid{margin-top:28px;gap:22px}\n  .propwall{padding:52px 0 44px}\n  .propwall h2{font-size:clamp(2.8rem,13.5vw,3.8rem)}\n}\n@media (max-width:380px){\n  .hero-stage{padding-top:84px}\n  .hero h1{font-size:min(19vw,4.4rem)}\n}\n\n.signup .form-consent{gap:12px}\n\n\n/* ---------- Round 3 (2026-11): fewer duplicates, playful stickers, calmer navigation ---------- */\n/* Menu opens without drawing a focus ring around the logo. */\ndialog.menu-sheet:focus{outline:none}\n/* Phones and tablets: the header keeps just the logo and Menu. Get on the list lives in the menu,\n   in the hero and in the bar at the bottom, so it does not need a fourth home up here. */\n@media (max-width:900px){.header-actions .header-cta{display:none}}\n\n/* Hero stickers you can pick up, throw, or tap to toss. */\n.hero-prop{appearance:none;-webkit-appearance:none;background:none;border:0;padding:0;margin:0;font:inherit;color:inherit;cursor:grab;touch-action:none;user-select:none;-webkit-user-select:none;transition:none}\n.hero-prop:focus-visible{outline:3px solid var(--blue);outline-offset:6px;border-radius:14px}\n.toy-body{display:block;position:relative;transition:scale .22s cubic-bezier(.2,.8,.2,1),translate .22s cubic-bezier(.2,.8,.2,1)}\n.toy-body>svg{width:100%;height:auto}\n.hero-prop:hover .toy-body{scale:1.04}\n.hero-prop.is-held{cursor:grabbing;z-index:6}\n.hero-prop.is-held .toy-body{scale:1.12;translate:0 -6px}\n.hero-prop.is-held>.toy-body>svg,.hero-prop.is-flying>.toy-body>svg{animation-play-state:paused}\n/* A clean light sweep across the sticker when you pick it up or toss it, like a glossy print catching the light. */\n.toy-body::after{content:\"\";position:absolute;inset:0;pointer-events:none;background:linear-gradient(115deg,transparent 35%,rgba(255,255,255,.55) 48%,transparent 60%) no-repeat;background-size:250% 100%;background-position:130% 0;-webkit-mask:var(--toy-mask,none);opacity:0;mix-blend-mode:soft-light}\n.hero-prop.is-held .toy-body::after,.hero-prop.is-tossed .toy-body::after{animation:toy-shine .7s ease-out}\n@keyframes toy-shine{0%{opacity:1;background-position:130% 0}100%{opacity:0;background-position:-30% 0}}\nhtml.js .hero-prop{animation:os-pop .8s cubic-bezier(.3,1.4,.5,1) both}\n.toy-hint{position:absolute;z-index:1;margin:0;font:italic 400 1.15rem/1.1 var(--serif);color:var(--red-text);pointer-events:none;white-space:nowrap;transition:opacity .4s ease;opacity:0;animation:os-fade .6s ease 2.4s both}\n.toy-hint::before{content:\"↖\";display:inline-block;margin-right:6px;font-style:normal;rotate:-10deg}\n.hero.toys-found .toy-hint{opacity:0!important;animation:none}\n@media (min-width:1001px){\n  .toy-hint{left:calc(-1 * clamp(150px,15vw,250px));bottom:-2px}\n  html.js .hero:not(.toys-found) .toy-hint{opacity:1}\n}\n/* Phones: the two stickers sit side by side above the card (never underneath it) and stay touchable. */\n@media (max-width:1000px){\n  .hero-prop{z-index:3}\n  .toy-hint{display:none}\n}\n@media (max-width:720px){\n  .hero-stage{padding:150px 0 28px}\n  .hero-prop--arch{top:6px;bottom:auto;left:-4px;right:auto;width:min(44%,190px)}\n  .hero-prop--bubble{top:20px;bottom:auto;right:-4px;left:auto;width:min(42%,176px)}\n  .hero-prop--arch>.toy-body>svg{rotate:-8deg}\n  .hero-prop--bubble>.toy-body>svg{rotate:7deg}\n}\n@media (max-width:380px){.hero-stage{padding-top:132px}}\n\n\n/* Prop wall: you can grab and drag it, swipe it, or scroll it. */\n.propwall-rail{cursor:grab;user-select:none;-webkit-user-select:none}\n.propwall-track{will-change:transform}\n.propwall-rail.is-dragging{cursor:grabbing}\n.propwall-rail.is-dragging a{pointer-events:none}\n.propwall-rail:focus-visible{outline:3px solid var(--yellow);outline-offset:-3px}\n.propwall-track img,.propwall-track svg{-webkit-user-drag:none;user-select:none}\n\n.toy-body>svg{animation:os-bob 7s ease-in-out infinite}\n.hero-prop--arch .toy-body>svg{rotate:-9deg}\n.hero-prop--bubble .toy-body>svg{rotate:8deg;animation-delay:-3.5s}\n@media (min-width:1001px){.hero-prop--bubble .toy-body>svg{rotate:-7deg}.hero-actions .btn--ghost{background:var(--ink);color:var(--paper);box-shadow:5px 5px 0 var(--red)}.hero-actions .btn--ghost:hover{box-shadow:7px 7px 0 var(--red)}}\nhtml.motion-paused .toy-body>svg{animation-play-state:paused!important}\n@media (prefers-reduced-motion:reduce){.toy-body>svg{animation:none}.toy-body::after{display:none}.toy-hint{animation:none;opacity:1}}\n\n/* ---------- Round 4 (2026-11): in-place actions, calmer labels, stickers that spring home ---------- */\n/* No section numbers; headings carry the page. */\n.section h2.big{margin-top:0}\n.story-head h2,.events-top h2,.propwall h2,.room h2,.home-join h2{margin-top:0}\n.about-actions{margin-top:4px}\n/* The sign-up card answers a \"Get on the list\" tap when it is already on screen. */\n.next-card.is-nudged{animation:os-nudge .6s cubic-bezier(.3,1.6,.45,1)}\n@keyframes os-nudge{0%{transform:none}30%{transform:translate(-4px,-6px) rotate(-.8deg);box-shadow:16px 16px 0 var(--red)}100%{transform:none}}\n/* Stickers spring back to their spot, so a drag never leaves a gap. While held they lift off the page. */\n.hero-prop.is-held .toy-body{scale:1.14;translate:0 -8px;filter:drop-shadow(0 18px 18px rgba(20,20,20,.28))}\n.toy-body{transition:scale .22s cubic-bezier(.2,.8,.2,1),translate .22s cubic-bezier(.2,.8,.2,1),filter .22s ease}\n/* Phones: the stickers tuck onto the top edge of the card like they were stuck there, instead of\n   holding a big empty band above it. */\n@media (max-width:720px){\n  .hero-stage{padding:64px 0 28px}\n  .hero-prop--arch{top:0;left:-8px;width:min(38%,156px)}\n  .hero-prop--bubble{top:8px;right:62px;width:min(36%,150px)}\n  .hero-prop{z-index:3}\n  .hero-stage .next-card{padding-top:58px}\n}\n@media (max-width:380px){.hero-stage{padding-top:56px}.hero-stage .next-card{padding-top:52px}}\n@media (prefers-reduced-motion:reduce){.next-card.is-nudged{animation:none}}\n\n/* ===== OffScript shared UI: footer, sheets (list, board, prop viewer), reactive logo =====\n   Used on the OffScript pages and, through the Worker, on every event page.\n   Every class is namespaced (osf-, os-) and sets its own type, so event styles cannot leak in. */\n.osf,.os-sheet{--os-ink:#141414;--os-paper:#faf4e7;--os-chalk:#fffdf5;--os-smoke:#5a554e;--os-blue:#1036af;--os-yellow:#ffd63b;--os-red:#e8382b;--os-mint:#aeef9d;\n  --os-display:Anton,Impact,\"Arial Narrow\",sans-serif;--os-body:\"Space Grotesk\",Space,\"Helvetica Neue\",Arial,sans-serif;--os-serif:\"Instrument Serif\",Georgia,\"Times New Roman\",serif;\n  --os-gutter:clamp(20px,5.5vw,100px);-webkit-font-smoothing:antialiased;box-sizing:border-box}\n.osf *,.osf *::before,.osf *::after,.os-sheet *,.os-sheet *::before,.os-sheet *::after{box-sizing:border-box}\n.os-visually-hidden{position:absolute!important;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n\n/* ---------- Footer ---------- */\n.osf{display:block;background:var(--os-ink);color:var(--os-paper);font:400 1rem/1.5 var(--os-body);letter-spacing:0;text-transform:none;margin:0;padding:0;border:0}\n.osf-wrap{width:100%;max-width:calc(1560px + 2 * var(--os-gutter));margin:0 auto;padding-left:var(--os-gutter);padding-right:var(--os-gutter)}\n.osf a{color:inherit}\n.osf svg{display:block}\n.osf a:focus-visible{outline:3px solid var(--os-yellow);outline-offset:4px}\n\n/* The one \"what's next\" moment, at the end of every page. */\n.osf-next{position:relative;overflow:hidden;isolation:isolate;background:var(--os-blue);border-bottom:6px solid var(--os-red)}\n.osf-next-in{display:flex;align-items:flex-end;justify-content:space-between;gap:28px 48px;padding-top:clamp(40px,5vw,64px);padding-bottom:clamp(40px,5vw,64px)}\n.osf-next h2{margin:0;font:400 clamp(3.4rem,7.2vw,7rem)/.9 var(--os-display);letter-spacing:-.015em;text-transform:uppercase;color:var(--os-paper)}\n.osf-next h2 span{color:var(--os-yellow)}\n.osf-next p{margin:16px 0 0;max-width:420px;font:400 clamp(1rem,1.3vw,1.12rem)/1.5 var(--os-body);color:var(--os-paper)}\n.osf-btn{position:relative;display:inline-flex;align-items:center;justify-content:space-between;gap:18px;flex:none;min-height:64px;padding:18px 26px;background:var(--os-yellow);color:var(--os-ink)!important;border:2px solid var(--os-ink);box-shadow:5px 5px 0 var(--os-red);font:700 .88rem/1 var(--os-body);letter-spacing:.08em;text-transform:uppercase;text-decoration:none;transition:transform .15s ease,box-shadow .15s ease}\n/* The red pen ring from the hero, circling the one action. */\n.osf-btn::before{content:\"\";position:absolute;inset:-22px -34px -26px -30px;border:4px solid var(--os-red);border-radius:50%;transform:rotate(-5deg);pointer-events:none}\n.osf-btn svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;transition:transform .2s ease}\n.osf-btn:hover{transform:translate(-2px,-2px);box-shadow:7px 7px 0 var(--os-red)}\n.osf-btn:hover svg{transform:translateX(3px)}\n.osf-btn:active{transform:translate(3px,3px);box-shadow:2px 2px 0 var(--os-red)}\n\n/* Logo, line and links. */\n.osf-main{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:end;gap:24px clamp(28px,5vw,88px);padding-top:clamp(44px,6vw,80px);padding-bottom:clamp(32px,4vw,48px)}\n.osf-logo{display:block;color:var(--os-paper);text-decoration:none;-webkit-tap-highlight-color:transparent;touch-action:manipulation}\n.osf-logo svg{height:clamp(150px,15vw,230px);width:auto;overflow:visible}\n.osf-tag{margin:0 0 6px;font:italic 400 clamp(1.5rem,2.2vw,2.1rem)/1.12 var(--os-serif);color:var(--os-paper)}\n.osf-links{display:grid;gap:2px;justify-items:end;margin-bottom:2px}\n.osf-links a{position:relative;display:inline-block;padding:4px 0;font:400 clamp(1.6rem,2.2vw,2.1rem)/1.05 var(--os-display);letter-spacing:.01em;text-transform:uppercase;text-decoration:none;color:var(--os-paper)}\n.osf-links a::after{content:\"\";position:absolute;left:0;right:0;bottom:2px;height:3px;background:var(--os-yellow);transform:scaleX(0);transform-origin:right;transition:transform .25s cubic-bezier(.2,.8,.2,1)}\n.osf-links a:hover{color:var(--os-yellow)}\n.osf-links a:hover::after{transform:scaleX(1);transform-origin:left}\n.osf-legal{display:flex;align-items:center;gap:8px 28px;flex-wrap:wrap;padding-top:18px;padding-bottom:calc(22px + env(safe-area-inset-bottom));border-top:1px solid #3a3733;font:400 .84rem/1.4 var(--os-body);color:#bdb6aa}\n.osf-legal a{display:inline-flex;align-items:center;gap:8px;min-height:44px;color:#bdb6aa;text-decoration:none}\n.osf-legal a:hover{color:var(--os-paper)}\n.osf-top{margin-left:auto}\n.osf-top svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}\n\n/* The reactive logo: each letter is its own shape. Near the pointer they lift, lean and warm up;\n   the flipped f does its own flip; a tap sends a wave through the word. */\n.osf-g{fill:currentColor;transform-box:fill-box;transform-origin:50% 100%;transform:translateY(var(--ty,0px)) rotate(var(--rot,0deg)) scale(var(--sc,1));transition:transform .45s cubic-bezier(.2,.9,.25,1.2),fill .3s ease}\n.osf-g.is-hot{fill:var(--os-yellow)}\n.osf-g.is-warm{fill:#ffe9a3}\n.osf-g--flip{transform-origin:50% 50%}\nhtml.js .osf-logo:not(.is-in) .osf-g{opacity:0}\n.osf-logo.is-in .osf-g{animation:osf-rise .7s cubic-bezier(.2,.8,.2,1) calc(var(--i) * 55ms) both}\n.osf-logo.is-settled .osf-g{animation:none;opacity:1}\n.osf-logo.is-flip .osf-g--flip{animation:osf-flip .8s cubic-bezier(.3,1.3,.5,1)}\n.osf-logo.is-wave .osf-g{animation:osf-hop .62s cubic-bezier(.3,1.5,.5,1) calc(var(--i) * 45ms) backwards}\n.osf-logo.is-wave .osf-g--flip{animation:osf-flip .8s cubic-bezier(.3,1.3,.5,1) calc(var(--i) * 45ms) backwards}\n@keyframes osf-rise{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}\n@keyframes osf-hop{0%,100%{transform:none}40%{transform:translateY(-14px) rotate(-4deg)}70%{transform:translateY(2px)}}\n@keyframes osf-flip{0%{transform:none}55%{transform:rotate(200deg) scale(1.15)}100%{transform:rotate(360deg)}}\n\n@media (max-width:860px){\n  .osf-next-in{flex-direction:column;align-items:stretch}\n  .osf-btn{width:100%}\n  .osf-btn{min-height:58px;padding:14px 20px;font-size:.82rem}\n  .osf-btn::before{display:none}\n  .osf-main{grid-template-columns:auto minmax(0,1fr);align-items:end;column-gap:22px}\n  .osf-logo svg{height:clamp(112px,30vw,160px)}\n  .osf-tag{font-size:clamp(1.3rem,5.4vw,1.8rem);margin-bottom:4px}\n  .osf-links{grid-column:1/-1;grid-template-columns:repeat(2,minmax(0,1fr));justify-items:stretch;gap:0 22px;margin-top:10px;border-top:1px solid #3a3733}\n  .osf-links a{display:flex;align-items:center;min-height:58px;padding:10px 0;border-bottom:1px solid #2c2a27;font-size:clamp(1.45rem,6.4vw,1.9rem)}\n  .osf-links a::after{display:none}\n  .osf-legal{gap:4px 18px}\n}\n@media (max-width:360px){.osf-links{column-gap:14px}.osf-legal{font-size:.78rem}}\n@media (prefers-reduced-motion:reduce){\n  .osf-g{transition:fill .2s ease}\n  .osf-logo .osf-g,.osf-logo.is-in .osf-g{animation:none!important;opacity:1;transform:none}\n  .osf-btn,.osf-btn svg{transition:none}\n}\n\n/* ---------- Sheets: one pattern for the list, the Connection Board and the prop viewer ----------\n   A bottom sheet on phones, a centred card on larger screens. Native <dialog>: Escape closes, focus stays inside. */\ndialog.os-sheet{position:fixed;inset:0;margin:0;padding:0;border:0;width:100%;max-width:100%;height:100%;max-height:100%;background:transparent;color:var(--os-ink);overflow:hidden;font:400 1rem/1.5 var(--os-body);letter-spacing:0;text-transform:none}\ndialog.os-sheet[open]{display:flex;align-items:center;justify-content:center;padding:24px}\ndialog.os-sheet::backdrop{background:rgba(20,20,20,.62);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px)}\ndialog.os-sheet:focus{outline:none}\n.os-sheet-card{position:relative;width:min(100%,520px);max-height:calc(100% - 8px);overflow:auto;overscroll-behavior:contain;background:var(--os-ink);color:var(--os-paper);border:2px solid var(--os-ink);box-shadow:10px 10px 0 var(--os-red);padding:clamp(28px,4vw,40px);opacity:0;transform:translateY(18px) scale(.98);transition:opacity .2s ease,transform .32s cubic-bezier(.2,.9,.25,1.1)}\ndialog.os-sheet.is-open .os-sheet-card{opacity:1;transform:none}\n.os-sheet-grip{display:none}\n.os-sheet-close{position:absolute;top:14px;right:14px;z-index:3;width:44px;height:44px;display:grid;place-items:center;margin:0;padding:0;background:transparent;color:inherit;border:2px solid currentColor;cursor:pointer;transition:background .15s ease,color .15s ease}\n.os-sheet-close svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round}\n.os-sheet-close:hover{background:var(--os-yellow);color:var(--os-ink);border-color:var(--os-yellow)}\n.os-sheet-close:focus-visible{outline:3px solid var(--os-yellow);outline-offset:3px}\n\n/* Sign-up, in the sheet and anywhere else a form uses .os-signup */\n.os-list h2{margin:4px 56px 12px 0;font:400 clamp(2.6rem,7vw,3.6rem)/.92 var(--os-display);letter-spacing:-.01em;text-transform:uppercase;color:var(--os-paper)}\n.os-list-sub{margin:0 0 24px;font:italic 400 clamp(1.3rem,3.6vw,1.6rem)/1.15 var(--os-serif);color:var(--os-paper)}\n.os-signup{position:relative;margin:0}\n.os-field{display:flex;border:2px solid var(--os-paper);background:var(--os-chalk)}\n.os-field:focus-within{outline:3px solid var(--os-yellow);outline-offset:3px}\n.os-field input{flex:1;min-width:0;margin:0;border:0;border-radius:0;background:transparent;padding:14px;font:500 1rem/1.2 var(--os-body);color:var(--os-ink);box-shadow:none}\n.os-field input::placeholder{color:#716b62}\n.os-field input:focus{outline:none}\n.os-field input[aria-invalid=\"true\"]{background:#fff0ee}\n.os-field button{display:inline-flex;align-items:center;gap:10px;margin:0;border:0;border-left:2px solid var(--os-ink);border-radius:0;background:var(--os-yellow);color:var(--os-ink);padding:0 18px;min-height:52px;font:700 .78rem/1 var(--os-body);letter-spacing:.1em;text-transform:uppercase;cursor:pointer}\n.os-field button svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}\n.os-field button:hover{background:#ffe27a}\n.os-field button[disabled]{cursor:progress;opacity:.75}\n.os-hp{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}\n.os-consent{display:flex;align-items:flex-start;gap:12px;margin-top:16px;color:var(--os-paper);font:400 .88rem/1.45 var(--os-body);cursor:pointer;text-transform:none;letter-spacing:0}\n.os-consent input{margin:2px 0 0;flex:none;width:18px;height:18px;accent-color:var(--os-yellow)}\n.os-msg{min-height:1.4em;margin:12px 0 0;font:400 .92rem/1.4 var(--os-body);color:var(--os-paper)}\n.os-msg.is-error{color:#ffb3aa}\n.os-msg.is-ok{color:var(--os-mint)}\n.os-msg.is-note{color:var(--os-yellow)}\n.os-fine{margin:4px 0 0;font:400 .8rem/1.45 var(--os-body);color:#bdb6aa}\n.os-fine a,.os-consent a{color:var(--os-yellow)}\n.os-signup.is-done .os-field,.os-signup.is-done .os-consent,.os-signup.is-done .os-fine{display:none}\n.os-signup.is-closed .os-field{border-color:#5a554e;background:#24221f}\n.os-signup.is-closed .os-field input{color:#bdb6aa}\n.os-signup.is-closed .os-field button{background:#33302c;color:#bdb6aa;cursor:not-allowed;opacity:1}\n.os-signup.is-closed .os-consent{opacity:.6;cursor:default}\n/* A real Edition 001 prop slaps onto the card when the sign-up goes through. */\n.os-stamp{display:block;width:min(72%,280px);margin:8px auto 0;pointer-events:none;rotate:-4deg;animation:os-slap .55s cubic-bezier(.3,1.6,.45,1) both}\n.next-card .os-stamp{position:absolute;right:-14px;top:-64px;width:min(46%,200px);margin:0;rotate:9deg;z-index:3}\n.os-stamp svg{width:100%;height:auto;display:block}\n@keyframes os-slap{0%{opacity:0;transform:scale(1.9) rotate(-14deg)}60%{opacity:1;transform:scale(.94)}100%{transform:none}}\n\n/* Connection Board */\n.os-board .os-sheet-card{width:min(100%,760px);height:min(88vh,860px);display:flex;flex-direction:column;padding:0;background:var(--os-paper);color:var(--os-ink);box-shadow:10px 10px 0 var(--os-blue)}\n.os-board-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 18px 16px 24px;background:var(--os-ink);color:var(--os-paper)}\n.os-board-head h2{margin:0;font:400 clamp(1.9rem,4vw,2.5rem)/1 var(--os-display);text-transform:uppercase;letter-spacing:0;color:var(--os-paper)}\n.os-board-head p{margin:6px 0 0;font:400 .9rem/1.4 var(--os-body);color:#d8d1c4}\n.os-board .os-sheet-close{position:static;flex:none}\n.os-board-body{position:relative;flex:1;min-height:0;background:#fff}\n.os-board-body iframe{position:absolute;inset:0;width:100%;height:100%;border:0;background:#fff;opacity:0;transition:opacity .3s ease}\n.os-board.is-ready .os-board-body iframe{opacity:1}\n.os-board-wait{position:absolute;inset:0;display:grid;place-content:center;justify-items:center;gap:14px;padding:24px;text-align:center;font:700 .78rem/1.4 var(--os-body);letter-spacing:.12em;text-transform:uppercase;color:var(--os-smoke)}\n.os-board-wait i{width:42px;height:42px;border:4px solid #e4dcc8;border-top-color:var(--os-red);border-radius:50%;animation:os-spin .8s linear infinite}\n.os-board.is-ready .os-board-wait{display:none}\n@keyframes os-spin{to{transform:rotate(360deg)}}\n.os-board-foot{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 24px;border-top:2px solid var(--os-ink);font:400 .84rem/1.4 var(--os-body)}\n.os-board-foot a{color:var(--os-blue);font-weight:700;text-underline-offset:4px;min-height:40px;display:inline-flex;align-items:center}\n\n/* Prop viewer */\n.os-viewer .os-sheet-card{width:min(100%,820px);padding:clamp(22px,3vw,36px);background:var(--os-paper);color:var(--os-ink);box-shadow:10px 10px 0 var(--os-ink)}\n.os-viewer .os-sheet-close{color:var(--os-ink)}\n.os-viewer-stage{position:relative;margin:30px 0 10px;touch-action:pan-y}\n.os-viewer-stage svg{width:100%;height:auto;display:block;transition:opacity .2s ease,transform .3s cubic-bezier(.2,.8,.2,1)}\n.os-viewer-stage.is-swapping svg{opacity:0;transform:translateX(calc(var(--dir,1) * 24px)) rotate(calc(var(--dir,1) * 2deg))}\n.os-viewer-bar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}\n.os-viewer-name{margin:0;font:400 clamp(1.8rem,4vw,2.6rem)/1 var(--os-display);text-transform:uppercase}\n.os-viewer-count{display:block;margin-top:6px;font:700 .74rem/1 var(--os-body);letter-spacing:.12em;color:var(--os-smoke)}\n.os-viewer-nav{display:flex;gap:10px;align-items:center}\n.os-viewer-nav button{width:48px;height:48px;display:grid;place-items:center;margin:0;padding:0;background:var(--os-paper);color:var(--os-ink);border:2px solid var(--os-ink);cursor:pointer}\n.os-viewer-nav button:hover{background:var(--os-yellow)}\n.os-viewer-nav svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}\n.os-viewer-go{display:inline-flex;align-items:center;gap:10px;min-height:48px;padding:0 18px;background:var(--os-ink);color:var(--os-paper);border:2px solid var(--os-ink);box-shadow:4px 4px 0 var(--os-red);font:700 .76rem/1 var(--os-body);letter-spacing:.08em;text-transform:uppercase;text-decoration:none}\n.os-viewer-go:hover{box-shadow:6px 6px 0 var(--os-red);transform:translate(-2px,-2px)}\n\n@media (max-width:640px){\n  dialog.os-sheet[open]{align-items:flex-end;padding:0}\n  .os-sheet-card{width:100%;max-height:calc(100% - 24px);border-left:0;border-right:0;border-bottom:0;box-shadow:none;padding:30px 20px calc(24px + env(safe-area-inset-bottom));transform:translateY(100%);transition:transform .38s cubic-bezier(.2,.9,.25,1),opacity .2s ease}\n  .os-sheet-grip{display:block;position:absolute;top:9px;left:50%;width:44px;height:4px;margin-left:-22px;border-radius:4px;background:#5a554e}\n  .os-sheet-close{top:16px;right:14px}\n  .os-field{flex-direction:column}\n  .os-field button{border-left:0;border-top:2px solid var(--os-ink);justify-content:center;min-height:52px}\n  .os-board .os-sheet-card{height:calc(100% - 28px);border-top:2px solid var(--os-ink)}\n  .os-board-head{padding:22px 14px 14px 20px}\n  .os-board-foot{padding:8px 20px calc(8px + env(safe-area-inset-bottom))}\n  .os-viewer .os-sheet-card{border-top:2px solid var(--os-ink);padding-top:34px}\n  .os-viewer-go{width:100%;justify-content:center}\n  .next-card .os-stamp{top:-64px;right:-6px;width:150px}\n}\n@media (prefers-reduced-motion:reduce){\n  .os-sheet-card,.os-viewer-stage svg{transition:none}\n  .os-stamp,.os-board-wait i{animation:none}\n}\n@media print{.osf-next,.os-sheet{display:none!important}}\n/* Shared dialog scroll lock: position restored by JS for mobile Safari. */\nhtml:has(dialog[open]){overscroll-behavior:none}\n.os-sheet-grip{touch-action:none}\nbody.os-scroll-locked{overscroll-behavior:none}\n";
