const OFFSCRIPT_ANALYTICS_JS="/* First-party, privacy-conscious Offscript measurements. No personal form data. */\n(() => {\n  \"use strict\";\n  if (!globalThis.crypto || !crypto.randomUUID || !globalThis.document) return;\n  if (location.pathname.startsWith(\"/analytics\")) return;\n  const BASE = \"/analytics/api/collect\";\n  const VISITOR = \"offscript-visitor-v1\";\n  const SESSION = \"offscript-session-v1\";\n  const PAUSE = \"offscript-analytics-paused\";\n  const LEGACY_PAUSE = \"myc-analytics-paused\";\n  const MILESTONES = [10, 30, 60, 180, 300, 600];\n  const DAY = () => new Date().toISOString().slice(0, 10);\n  const pagePath = location.pathname;\n  const safe = value => String(value || \"\").replace(/[^a-zA-Z0-9_ .:/-]/g,\"\").slice(0, 80);\n  const storage = (kind) => { try {return window[kind]} catch{return null} };\n  const local = storage(\"localStorage\"), temporary = storage(\"sessionStorage\");\n  const paused = () => navigator.globalPrivacyControl === true ||\n    local?.getItem(PAUSE) === \"1\" || local?.getItem(LEGACY_PAUSE) === \"1\";\n  let visitorId, session;\n  function ids() {\n    if (paused()) return false;\n    if (!visitorId) {\n      visitorId = local?.getItem(VISITOR);\n      if (!visitorId || !/^[a-f0-9-]{36}$/i.test(visitorId)) {\n        visitorId = crypto.randomUUID();\n        try {local?.setItem(VISITOR,visitorId)} catch {}\n      }\n    }\n    const now = Date.now();\n    if (!session || now - Number(session.updatedAt || 0) > 1800000 || session.day !== DAY()) {\n      try {session = JSON.parse(temporary?.getItem(SESSION) || \"null\")} catch {session = null}\n      if (!session?.id || session.day !== DAY() || now - Number(session.updatedAt || 0) > 1800000) {\n        session = { id: crypto.randomUUID(),day:DAY(),updatedAt:now };\n      }\n    }\n    session.updatedAt = now;\n    try {temporary?.setItem(SESSION,JSON.stringify(session))} catch {}\n    return true;\n  }\n  function attribution() {\n    let saved = null;\n    try {saved=JSON.parse(temporary?.getItem(\"offscript-attribution-v1\") || \"null\")} catch {}\n    if (saved && typeof saved.source === \"string\") return saved;\n    const url=new URLSearchParams(location.search);\n    let referral=\"\";\n    try {\n      const ref=new URL(document.referrer);\n      if (ref.hostname !== location.hostname) referral = ref.hostname;\n    } catch {}\n    const details = {\n      source:safe(url.get(\"utm_source\") || referral || \"Direct / unknown\"),\n      campaign:safe(url.get(\"utm_campaign\") || \"None\")\n    };\n    try {temporary?.setItem(\"offscript-attribution-v1\",JSON.stringify(details))} catch {}\n    return details;\n  }\n  function track(eventName, milestoneSeconds) {\n    if (!ids()) return;\n    const payload={eventId:crypto.randomUUID(),visitorId,sessionId:session.id,\n      eventName,pagePath,attribution:attribution()};\n    if (eventName === \"engagement\") payload.milestoneSeconds = milestoneSeconds;\n    try {\n      void fetch(BASE,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},\n        keepalive:true,credentials:\"omit\",body:JSON.stringify(payload)}).catch(()=>{});\n    }catch{}\n  }\n  const toggle=document.querySelector(\"[data-offscript-analytics-toggle]\");\n  if (toggle) {\n    const update=()=>{\n      toggle.textContent = navigator.globalPrivacyControl === true ? \"Tracking paused by your browser\" :\n        paused() ? \"Resume anonymous analytics\" : \"Pause anonymous analytics\";\n      toggle.disabled = navigator.globalPrivacyControl === true;\n      toggle.setAttribute(\"aria-pressed\",paused()?\"true\":\"false\");\n    };\n    toggle.addEventListener(\"click\",()=>{\n      const next=paused()?\"0\":\"1\";\n      try {local?.setItem(PAUSE,next);local?.setItem(LEGACY_PAUSE,next)} catch {}\n      update();\n      location.reload();\n    });\n    update();\n  }\n  if(paused())return;\n  track(\"page_view\");\n  if(document.visibilityState === \"visible\") track(\"presence\");\n  let visibleSince = document.visibilityState === \"visible\" ? performance.now() : null;\n  let totalVisible = 0;\n  const fired = new Set();\n  function progress() {\n    const current=totalVisible + (visibleSince===null?0:Math.max(0,performance.now()-visibleSince));\n    for (const second of MILESTONES) {\n      if (current >= second * 1000 && !fired.has(second)) {\n        fired.add(second);track(\"engagement\",second);\n      }\n    }\n  }\n  document.addEventListener(\"visibilitychange\",()=>{\n    if(document.visibilityState===\"hidden\"){\n      if(visibleSince!==null) totalVisible += Math.max(0,performance.now()-visibleSince);\n      visibleSince=null;progress();\n    }else{\n      visibleSince=performance.now();track(\"presence\");\n    }\n  });\n  const milestoneInterval=setInterval(()=>{if(visibleSince!==null&&!paused())progress()},1000);\n  const presenceInterval=setInterval(()=>{if(document.visibilityState===\"visible\"&&!paused())track(\"presence\")},30000);\n  window.addEventListener(\"pagehide\",()=>{if(visibleSince!==null)totalVisible += Math.max(0,performance.now()-visibleSince);\n    visibleSince=null;progress();clearInterval(milestoneInterval);clearInterval(presenceInterval)});\n  document.addEventListener(\"offscript:signup-success\",()=>track(\"signup_success\"));\n  document.addEventListener(\"submit\",e=>{\n    if(e.target?.matches?.(\"form[data-signup]\") && e.target.checkValidity())track(\"signup_submit\");\n  },true);\n  document.addEventListener(\"click\",e=>{\n    const link=e.target?.closest?.(\"a,button\");\n    if(!link)return;\n    const href=link.getAttribute(\"href\")||\"\";\n    const action=link.hasAttribute(\"data-os-list\")||link.hasAttribute(\"data-focus-signup\")||href===\"#list\" ? \"signup_open\" :\n      /forms\\.gle|connection.board/i.test(href) ? \"board_open\" :\n      /props\\.html|prop.studio/i.test(href) ? \"prop_open\" :\n      /venue-explore\\.html/.test(href) ? \"venue_open\" :\n      /\\/events\\//.test(href) ? \"event_open\" :\n      /share/i.test(link.getAttribute(\"data-action\")||\"\") ? \"share_click\" :\n      link.closest(\"header,nav,footer\") && href ? \"nav_click\" : \"\";\n    if(action)track(action);\n  },true);\n})();\n";
const ORIGIN="https://makeyourcase.vercel.app";
const EVENT="/events/pitch-night-001";
const PUBLIC="https://offscriptgh.com";
export default {fetch(request,env,ctx){return handle(request,env,ctx)}};
function isPreview(url){return url.hostname.endsWith(".workers.dev")}
function headersBase(){return {"X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin"}}
function htmlResponse(page,request){
 const u=new URL(request.url);
 const headers={"Content-Type":"text/html; charset=utf-8","Cache-Control":"public, max-age=120",...headersBase()};
 if(isPreview(u))headers["X-Robots-Tag"]="noindex";
 return new Response(page.replace("</head>",'<script src="/offscript-analytics.js" defer></script></head>'),{status:200,headers});
}
async function handle(request,env,ctx){
 const url=new URL(request.url);
 const path=url.pathname;
 if(url.hostname==="www.offscriptgh.com") return Response.redirect("https://offscriptgh.com"+path+url.search+url.hash,308);

 if(path==="/favicon.svg"||path===EVENT+"/favicon.svg")return new Response(FAVICON_SVG,{headers:{"Content-Type":"image/svg+xml","Cache-Control":"public, max-age=86400","X-Content-Type-Options":"nosniff"}});
 if(path==="/apple-touch-icon.png"||path===EVENT+"/apple-touch-icon.png")return new Response(Uint8Array.from(atob(TOUCH_ICON_B64),c=>c.charCodeAt(0)),{headers:{"Content-Type":"image/png","Cache-Control":"public, max-age=86400","X-Content-Type-Options":"nosniff"}});
 if(path==="/offscript-serif.woff2")return new Response(Uint8Array.from(atob(FONT_SERIF_B64),c=>c.charCodeAt(0)),{headers:{"Content-Type":"font/woff2","Cache-Control":"public, max-age=31536000, immutable","X-Content-Type-Options":"nosniff"}});
 if(path==="/offscript-bridge.css")return new Response(BRIDGE_CSS,{headers:{"Content-Type":"text/css; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"}});
 if(path==="/offscript-bridge.js")return new Response(BRIDGE_JS,{headers:{"Content-Type":"text/javascript; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"}});
 if(path==="/offscript-analytics.js")return new Response(OFFSCRIPT_ANALYTICS_JS,{headers:{"Content-Type":"text/javascript; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"}});
 if(path==="/offscript.css")return new Response(BRAND_CSS,{headers:{"Content-Type":"text/css; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"}});
 if(path==="/robots.txt")return new Response("User-agent: *\nAllow: /\nSitemap: https://offscriptgh.com/sitemap.xml\n",{headers:{"Content-Type":"text/plain; charset=utf-8"}});
 if(path==="/sitemap.xml")return new Response('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+["/","/about/","/events/","/join/","/events/pitch-night-001/"].map(p=>'<url><loc>https://offscriptgh.com'+p+'</loc></url>').join("")+"</urlset>",{headers:{"Content-Type":"application/xml; charset=utf-8"}});
 for(const p of ["/about","/events","/join","/privacy"])if(path===p)return Response.redirect(url.origin+p+"/"+url.search,308);
 if(path==="/about/")return htmlResponse(PAGE_ABOUT,request);
 if(path==="/events/")return htmlResponse(PAGE_EVENTS,request);
 if(path==="/join/")return htmlResponse(PAGE_JOIN,request);
 if(path==="/privacy/")return htmlResponse(PAGE_PRIVACY,request);
 if(path==="/api/list-status")return request.method==="GET"?dataOut({open:Boolean(env.OFFSCRIPT_DB&&env.RESEND_API_KEY&&env.SUBSCRIBE_SIGNING_SECRET)}):dataOut({error:"Method not allowed"},405);
 if(path==="/api/subscribe")return signup(request,env);
 if(path==="/confirm")return confirmEmail(request,env);
 if(path==="/unsubscribe")return unsubscribeEmail(request,env);
 if(path==="/"){
  if(request.method!=="GET"&&request.method!=="HEAD")return new Response("Method not allowed",{status:405});
  return htmlResponse(HOME,request);
 }
 if(path==="/analytics"||path.startsWith("/analytics/"))return forwardAnalytics(request,env);
 if(path===EVENT) return Response.redirect(url.origin+EVENT+"/"+url.search,308);
 if(path.startsWith(EVENT+"/")) return forward(request,path.slice(EVENT.length)||"/",true);
 if(path==="/site-feedback.html")return Response.redirect(url.origin+EVENT+"/site-feedback.html",308);
 if(path.startsWith("/api/")||path.startsWith("/admin/"))return forward(request,path,false);
 if(path.startsWith("/assets/"))return forward(request,path,false);
 return new Response("Page not found",{status:404,headers:{"Content-Type":"text/plain; charset=utf-8",...headersBase()}});
}
async function forwardAnalytics(request,env){
 const configured=String(env.OFFSCRIPT_ANALYTICS_ORIGIN||"").replace(/\/$/,"");
 if(!/^https:\/\/[a-z0-9.-]+(?::443)?$/i.test(configured))return new Response("Offscript analytics has not been configured.",{status:503,headers:{"Content-Type":"text/plain; charset=utf-8","Cache-Control":"no-store"}});
 const input=new URL(request.url);
 const target=new URL(input.pathname+input.search,configured);
 const headers=new Headers(request.headers);
 headers.delete("host");
 headers.delete("x-forwarded-for");
 headers.delete("x-offscript-country");
 headers.delete("x-offscript-client-ip");
 const country=request.cf?.country||"";
 headers.set("x-offscript-country",/^[A-Z]{2}$/.test(country)?country:"");
 headers.set("x-offscript-client-ip",request.headers.get("cf-connecting-ip")||"unknown");
 headers.delete("cf-connecting-ip");
 let upstream;
 try{upstream=await fetch(new Request(target.toString(),{
  method:request.method,headers,body:request.method==="GET"||request.method==="HEAD"?undefined:request.body,
  redirect:"manual"
 }))}catch{return new Response("Analytics is temporarily unavailable.",{status:502,headers:{"Cache-Control":"no-store"}})}
 const responseHeaders=new Headers(upstream.headers);
 responseHeaders.set("X-Content-Type-Options","nosniff");
 if(!input.pathname.includes("/_next/static/"))responseHeaders.set("Cache-Control","private, no-store");
 const location=responseHeaders.get("Location");
 if(location){
  const destination=new URL(location,target);
  if(destination.origin===new URL(configured).origin)responseHeaders.set("Location",input.origin+destination.pathname+destination.search+destination.hash);
 }
 return new Response(upstream.body,{status:upstream.status,headers:responseHeaders});
}

async function forward(request,path,eventPage){
 const incoming=new URL(request.url),target=new URL(ORIGIN);
 target.pathname=path;
 target.search=incoming.search;
 const method=request.method;
 const allowed=["GET","HEAD","POST","PUT","DELETE","OPTIONS"];
 if(!allowed.includes(method))return new Response("Method not allowed",{status:405});
 const upstreamHeaders=new Headers(request.headers);
 upstreamHeaders.delete("host");
 upstreamHeaders.delete("x-forwarded-host");
 upstreamHeaders.delete("x-forwarded-proto");
 upstreamHeaders.delete("cf-connecting-ip");
 upstreamHeaders.delete("cf-ipcountry");
 upstreamHeaders.delete("cf-ray");
 // Only the publicly served Offscript origin can send cross-origin-protected writes.
 if(!["GET","HEAD","OPTIONS"].includes(method)&&path.startsWith("/api/")){
  if(upstreamHeaders.get("origin")!==incoming.origin) return new Response("Origin refused",{status:403});
  upstreamHeaders.set("origin",ORIGIN);
 }
 let upstream;
 try{
  upstream=await fetch(new Request(target.toString(),{
   method,headers:upstreamHeaders,body:["GET","HEAD"].includes(method)?undefined:request.body,redirect:"manual"
  }));
 }catch(e){return new Response("Event page temporarily unavailable",{status:502,headers:{"Cache-Control":"no-store"}})}
 const responseHeaders=new Headers(upstream.headers);
 responseHeaders.set("X-Content-Type-Options","nosniff");
 if(isPreview(incoming))responseHeaders.set("X-Robots-Tag","noindex");
 const loc=responseHeaders.get("Location");
 if(loc){
   const dest=new URL(loc,target);
   if(dest.origin===ORIGIN){
     responseHeaders.set("Location",incoming.origin+(eventPage?EVENT:"")+dest.pathname+dest.search+dest.hash);
   }
 }
 const ct=(responseHeaders.get("Content-Type")||"").toLowerCase();
 if(eventPage&&ct.includes("text/html")&&method==="GET"&&upstream.status===200){
  let html=await upstream.text();
  // Absolute-root resources in the archive must continue resolving inside the archive.
  html=html.replace(/(href|src)=(["'])\/(?!\/|assets\/fonts\/)/gi,(full,attr,q)=>attr+"="+q+EVENT+"/");
  html=html.replaceAll(ORIGIN,PUBLIC+EVENT);
  html=familyLayer(html,path);
  if(path==="/"||path==="/index.html"){
    html=html.replace("</head>",'<link rel="canonical" href="'+PUBLIC+EVENT+'/"/></head>');
  }
  for(const h of ["Content-Length","Content-Encoding","ETag"])responseHeaders.delete(h);
  return new Response(html,{status:upstream.status,headers:responseHeaders});
 }
 return new Response(upstream.body,{status:upstream.status,headers:responseHeaders});
}


// One OffScript family layer on every event page: brand bar, shared fonts, favicon and footer.
const EVENT_PAGES={"/":"Pitch Night 001","/index.html":"Pitch Night 001","/props.html":"Prop Studio","/venue-explore.html":"The venue","/thank-you-card.html":"Thank-you card","/site-feedback.html":"Site feedback"};
function familyLayer(html,path){
 const here=EVENT_PAGES[path];
 const isMain=!here||here==="Pitch Night 001";
 // One breadcrumb, written once: OffScript / Events / Pitch Night 001 (/ sub page). No second bar on top.
 const crumbs='<nav class="osx-crumbs" aria-label="Breadcrumb"><a href="/">OffScript</a><span aria-hidden="true">/</span><a href="/events/">Events</a><span aria-hidden="true">/</span>'+(isMain?'<span aria-current="page">Pitch Night 001</span>':'<a href="'+EVENT+'/">Pitch Night 001</a><span aria-hidden="true">/</span><span aria-current="page">'+here+'</span>')+'</nav>';
 // The OffScript logo always leads home to the parent brand.
 html=html.replace(/<a class="(brand|footer-brand|prop-brand|head-logo)" href="[^"]*"(?: aria-label="[^"]*")?/g,'<a class="$1" href="/" aria-label="OffScript home"');
 html=html.replace(/(<a\b[^>]*?\shref=)(["'])https:\/\/offscriptgh\.com\//g,'$1$2/');
 // Self-hosted fonts replace the Google Fonts request.
 html=html.replace(/<link[^>]+fonts\.(googleapis|gstatic)\.com[^>]*>/gi,"").replace(/<noscript>\s*<\/noscript>/gi,"");
 html=html.replace(/<link rel="icon"[^>]*>/i,"");
 html=html.replace("</head>",'<link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="stylesheet" href="/offscript-bridge.css"><script src="/offscript-bridge.js" defer></script><script src="/offscript-analytics.js" defer></script></head>');
 const topline=/<span class="v2-topline-left post-archive-label">[^<]*<\/span>/;
 if(isMain&&topline.test(html)){
  // The event's own "OffScript / Edition 001" line becomes the real, clickable breadcrumb.
  html=html.replace(topline,crumbs);
 }else{
  const strip='<div class="osx-crumb-strip">'+crumbs+'</div>';
  if(/<a class="skip-link"[^>]*>[\s\S]*?<\/a>/.test(html))html=html.replace(/(<a class="skip-link"[^>]*>[\s\S]*?<\/a>)/,(m)=>m+strip);
  else html=html.replace(/<body\b[^>]*>/i,all=>all+strip);
 }
 // One footer on every event page: the OffScript footer below carries the event links,
 // so the page's own small footer (logo, "back to the event", edition line) is removed.
 html=html.replace(/<footer\b[^>]*>[\s\S]*?<\/footer>/gi,"");
 // The event menu ends with a way back to the rest of OffScript.
 html=html.replace(/<p class="site-menu-foot">[^<]*<\/p>/,'<p class="site-menu-foot osx-menu-home"><a href="/">← OffScript home</a><a href="/events/">All events</a><a href="/#list" data-os-list>Get on the list</a></p>');
 // The OffScript footer now closes every page, so the event's own sign-off band would repeat it.
 html=html.replace(/<section class="post-final"[\s\S]*?<\/section>/i,"");
 // The event's analytics pop-up is retired everywhere except the site feedback page, where its pause control lives.
 if(path!=="/site-feedback.html")html=html.replace(/<aside class="measurement-notice"[\s\S]*?<\/aside>/i,"");
 html=html.replace(/<\/body>/i,BRIDGE_FOOT+"</body>");
 return html;
}

